// A-02, in the only form that does not need a settings screen: one table you
// edit here. Every record created or changed in the portal arrives at this
// webhook; each rule that matches produces one notification.
//
//   when   : 'created' | 'changed' | 'any'
//   form   : form code, or '*' for every register
//   field  : (changed only) the field that must have changed
//   equals : (optional) the new value it must have become
//   to     : email address, or 'OWNER' to use the record's own owner field
//   also   : optional extra channels - 'whatsapp', 'slack'
//   say    : the message, with {field} placeholders from the record
const RULES = [
  { when: 'changed', form: 'TXN-005', field: 'status', equals: 'Closed',
    to: 'finance@dharanis.ae', also: 'slack',
    say: 'Transaction {transaction_ref} closed on {closing_date}. Raise the commission calculation and the invoice.' },

  { when: 'changed', form: 'CMP-002', field: 'status', equals: 'High Risk',
    to: 'compliance@dharanis.ae', also: 'whatsapp,slack',
    say: 'AML risk on {client_name} has been rated HIGH. Enhanced due diligence and a re-screening date are needed now, before the transaction proceeds.' },

  { when: 'created', form: 'CMP-006',
    to: 'compliance@dharanis.ae', also: 'whatsapp,slack',
    say: 'A suspicious activity escalation has been raised. This is a goAML clock - open it immediately.' },

  { when: 'created', form: 'IT-008',
    to: 'it@dharanis.ae', also: 'slack',
    say: 'Security incident logged: {subject}. Severity {priority}.' },

  { when: 'changed', form: 'PRO-001', field: 'status', equals: 'Under Offer',
    to: 'OWNER', also: 'slack',
    say: 'Property {property_ref} is now Under Offer. Pull it from the portals and tell the owner.' },

  { when: 'created', form: 'HR-012',
    to: 'hr@dharanis.ae',
    say: 'A grievance has been filed by {employee_name}. Acknowledge it within the policy window.' },

  { when: 'created', form: 'FIN-007',
    to: 'finance@dharanis.ae', also: 'whatsapp',
    say: 'BANK DETAIL CHANGE requested for {vendor_name}. Verify by phone on a number you already hold - never one from the request itself - before approving.' },
];

const cfg = $('Config').first().json;
const e = $json.body || $json;
const data = e.data || {};
const changed = e.changed_fields || {};
const kind = String(e.event || '').includes('created') ? 'created' : 'changed';

const fill = (tpl) => String(tpl).replace(/\{(\w+)\}/g, (_, k) =>
  (data[k] !== undefined && data[k] !== null && data[k] !== '') ? data[k] : '-');

const OWNER_FIELDS = ['responsible_person','owner_name','agent_name','assigned_employee',
                      'employee_name','agent_assigned','vendor_name','requested_by'];

const out = [];
for (const r of RULES) {
  if (r.when !== 'any' && r.when !== kind) continue;
  if (r.form !== '*' && r.form !== e.form_code) continue;
  if (r.when === 'changed' && r.field) {
    if (!(r.field in changed)) continue;
    if (r.equals !== undefined && String(changed[r.field]) !== String(r.equals)) continue;
  }
  let to = r.to;
  if (to === 'OWNER') {
    const f = OWNER_FIELDS.find(k => data[k]);
    to = f ? (data[f] + '') : cfg.fallback_email;
    if (!to.includes('@')) to = cfg.fallback_email;   // it was a name, not an address
  }
  out.push({ json: {
    channel: ['email'].concat(String(r.also || '').split(',').filter(Boolean)).join(','),
    to_email: to,
    slack_channel: cfg.slack_channel,
    subject: `[DHARANI 360] ${e.form_code} ${e.doc_no}`,
    message: fill(r.say)
      + `\n\nRecord: ${cfg.portal_url}/record/${e.form_code}/${e.record_id}`
      + `\nChanged by: ${e.actor || 'unknown'}`,
  }});
}
return out;
